<?php
declare(strict_types=1);
require_once __DIR__ . '/includes/layout.php';
$user=require_admin();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$provider=(string)($_POST['provider']??'');if(!in_array($provider,['rd_crm','rd_marketing','openai'],true))throw new RuntimeException('Integração inválida.');$current=integration_get($pdo,$provider);$secret=trim((string)($_POST['client_secret']??''));$access=trim((string)($_POST['access_token']??''));$refresh=trim((string)($_POST['refresh_token']??''));$data=['client_id'=>trim((string)($_POST['client_id']??''))?:($current['client_id']??null),'client_secret'=>$secret!==''?$secret:secret_decrypt($current['client_secret']??''),'access_token'=>$access!==''?$access:secret_decrypt($current['access_token']??''),'refresh_token'=>$refresh!==''?$refresh:secret_decrypt($current['refresh_token']??''),'is_active'=>isset($_POST['is_active']),'extra'=>['model'=>trim((string)($_POST['model']??''))]];integration_upsert($pdo,$provider,$data,(int)$user['id']);audit($pdo,(int)$user['id'],'configure','integration',null,['provider'=>$provider]);flash('success','Configuração salva com credenciais protegidas.');}catch(Throwable $e){flash('danger',$e->getMessage());}redirect('configuracoes.php');}
$providers=['rd_crm'=>['RD Station CRM','OAuth para negociações, empresas, contatos e usuários.'],'rd_marketing'=>['RD Station Marketing','Base de leads, conversões e contexto de marketing.'],'openai'=>['ChatGPT / OpenAI','Assistência de IA acionada somente pelo backend PHP.']];
$configs=[];foreach(array_keys($providers) as $p)$configs[$p]=integration_get($pdo,$p);
$lines=$pdo->query('SELECT pl.*,f.label funnel_label FROM product_lines pl JOIN funnels f ON f.funnel_key=pl.funnel_key ORDER BY pl.sort_order')->fetchAll();
page_header('Configurações','configuracoes');
?>
<div class="page-actions"><div><span class="eyebrow">ADMINISTRAÇÃO</span><h2>Integrações</h2><p>As credenciais são informadas nesta tela e armazenadas criptografadas no banco.</p></div></div>
<div class="integration-grid"><?php foreach($providers as $key=>[$title,$desc]):$cfg=$configs[$key];$extra=json_decode((string)($cfg['extra_json']??'{}'),true)?:[]; ?><div class="card integration-card"><div class="card-title"><div><span class="tag"><?= e(strtoupper($key)) ?></span><h3><?= e($title) ?></h3><p><?= e($desc) ?></p></div><span class="dot <?= !empty($cfg['is_active'])?'on':'' ?>"></span></div><form method="post" class="stack-form"><?= csrf_field() ?><input type="hidden" name="provider" value="<?= e($key) ?>"><?php if($key!=='openai'): ?><label><span>Client ID</span><input name="client_id" value="<?= e($cfg['client_id']??'') ?>"></label><label><span>Client Secret</span><input name="client_secret" type="password" placeholder="<?= !empty($cfg['client_secret'])?'•••••••• salvo':'informe o segredo' ?>"></label><label><span>Access Token</span><input name="access_token" type="password" placeholder="<?= !empty($cfg['access_token'])?'•••••••• salvo':'opcional / OAuth' ?>"></label><label><span>Refresh Token</span><input name="refresh_token" type="password" placeholder="<?= !empty($cfg['refresh_token'])?'•••••••• salvo':'opcional / OAuth' ?>"></label><?php else: ?><label><span>API Key</span><input name="access_token" type="password" placeholder="<?= !empty($cfg['access_token'])?'•••••••• salva':'API Key' ?>"></label><label><span>Modelo</span><input name="model" value="<?= e($extra['model']??'') ?>" placeholder="definiremos na integração"></label><?php endif; ?><label class="toggle"><input type="checkbox" name="is_active" value="1" <?= !empty($cfg['is_active'])?'checked':'' ?>><span>Integração ativa</span></label><button class="btn btn-primary" type="submit">Salvar configuração</button></form></div><?php endforeach; ?></div>
<div class="card"><div class="card-title"><div><span class="tag">ESTRUTURA DO MODELO</span><h3>Linhas de produto e funil automático</h3><p>Itens estruturais trazidos do HTML, sem registros comerciais de demonstração.</p></div></div><div class="table-wrap"><table><thead><tr><th>Linha</th><th>Funil</th><th>Tipo</th><th>Agenciamento</th></tr></thead><tbody><?php foreach($lines as $line): ?><tr><td><strong><?= e($line['name']) ?></strong></td><td><?= e($line['funnel_label']) ?></td><td><?= e($line['item_type']) ?></td><td><?= (int)$line['is_agency']?'Sim':'Não' ?></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php page_footer(); ?>